import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import 'package:provider/provider.dart'; import '../providers/permission_provider.dart'; import '../widgets/permission_tile.dart'; class PermissionsPage extends StatelessWidget{const PermissionsPage({super.key});@override Widget build(BuildContext c){final p=c.watch<PermissionProvider>();return Scaffold(appBar:AppBar(title:const Text('الصلاحيات')),body:RefreshIndicator(onRefresh:p.refresh,child:ListView(padding:const EdgeInsets.all(20),children:[PermissionTile(icon:Icons.camera_alt_outlined,title:'الكاميرا',subtitle:'تحليل محلي للعينين.',granted:p.camera,onPressed:p.requestCamera),PermissionTile(icon:Icons.layers_outlined,title:'العرض فوق التطبيقات',subtitle:'لعرض مؤشر النظر.',granted:p.overlay,onPressed:p.requestOverlay),PermissionTile(icon:Icons.accessibility_new,title:'إمكانية الوصول',subtitle:'لتنفيذ النقر بالنظر.',granted:p.accessibility,onPressed:p.requestAccessibility),const SizedBox(height:12),FilledButton(onPressed:p.ready?()=>c.go('/tracking'):null,child:const Text('متابعة إلى التتبع'))])));}}